"""Explain reliable preconditions, empty versus unsupported and user stacks."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1953': ('공책이 치워지지 않게 잡아 두는 것과 누군가 계속 쓰지 않도록 하는 것은 달라요. 스택을 읽을 때도 수명과 실행 상태를 따로 확인해요.', '다른 태스크의 비활성 조건과 스택 수명 보호를 구분합니다.', '태스크가 실행 중이지 않음·스택이 읽는 동안 유지됨을 두 칸에 쓰세요. 한 칸을 만족했다고 다른 칸이 자동 충족되지는 않아요.', ['reliable 스택 추적은 호출 경로를 신뢰할 수 있는지 판정하며 모으는 기능이에요. 태스크는 커널이 관리하는 실행 주체이고 current는 지금 실행 중인 태스크예요. 다른 태스크를 읽는 경우에는 그 태스크의 상태가 바뀔 수 있다는 점을 고려해야 해요.', 'arch_stack_walk_reliable의 헤더는 대상이 current가 아니면 비활성이어야 하고 스택이 pinned 상태여야 한다고 요구해요. 여기서 pinned는 읽는 동안 스택 메모리가 해제되지 않도록 수명을 확보한다는 뜻이에요. CPU 하나에 묶어 실행한다는 의미와 혼동하지 않아요.', '비활성 조건은 그 태스크가 실행하며 스택을 계속 바꾸지 않도록 하는 조건이에요. 메모리가 아직 있다는 것만으로 그 내용도 안정됐다고 할 수 없어요. 책이 책상에 계속 놓여 있어도 누군가 내용을 고칠 수 있는 것과 비슷해요.', '공통 stack_trace_save_tsk_reliable은 try_get_task_stack으로 스택 사용 수명을 확보하고, walker 호출 뒤 put_task_stack으로 마무리해요. 하지만 그 본문에는 다른 태스크를 직접 정지시키는 코드가 없어요.', '따라서 공통 wrapper를 부르는 쪽은 다른 태스크가 비활성이라는 조건을 마련해야 해요. 아키텍처 walker를 직접 사용하는 쪽은 헤더의 스택 고정 조건까지 충족해야 해요. 이미 wrapper가 맡는 수명 준비와 호출자가 따로 맡는 실행 상태 준비를 나누어 봐요.', '종이의 순차 예제에서 태스크 객체가 가만히 있다는 사실은 실제 커널의 비활성화 절차를 검증한 것이 아니에요. 실제 사용법을 판단할 때는 호출 경로가 상태를 어떻게 보장하는지와 CPU별 신뢰성 판정 코드를 함께 확인해요.'], [('다른 태스크를 arch reliable walker로 추적할 때 필요한 조건은 무엇인가요?', ['그 태스크가 최대 속도로 계속 실행 중이어야 해요', '태스크가 비활성이며 읽는 동안 스택 수명이 유지돼야 해요'], '정답은 두 번째예요. 헤더는 inactive와 pinned 조건을 함께 요구해요. 스택이 사라지지 않는 것과 태스크가 실행하며 내용을 바꾸지 않는 것은 별개예요.'), ('공통 reliable wrapper가 다른 태스크를 직접 정지시키나요?', ['아니요. 비활성 조건은 호출한 쪽이 마련해야 해요', '네. 스택 getter가 모든 태스크를 정지시켜요'], '정답은 첫 번째예요. wrapper는 스택 확보·탐색·반납을 해요. 참조를 얻는 동작을 태스크 실행을 멈추는 동작으로 해석하면 안 돼요.')]), 'os1954': ('찾아볼 공책 자체가 없는 경우와 공책을 읽는 기능이 없는 경우는 달라요. 이 함수도 빈 결과와 미지원 오류를 다른 값으로 알려요.', '스택 부재의 0 반환과 검증·미지원 오류를 구분합니다.', '스택 없음은 0, 기능 미지원은 -ENOSYS, 검증 실패는 해당 음수 오류로 세 칸을 만드세요.', ['reliable wrapper는 먼저 try_get_task_stack으로 대상 스택을 얻으려 해요. 이 호출이 실패하면 바로 0을 반환해요. 원문 주석은 종료 뒤 스택이 없는 태스크 같은 경우를 신뢰할 수 있게 비어 있는 스택으로 다룬다고 설명해요.', '주석의 zombie는 실행은 끝났지만 부모가 종료 정보를 거두기 전까지 관리 정보가 남는 상태를 가리켜요. 그 예를 든 것이며 모든 종료 태스크의 세부 수명을 이 한 함수가 판정한다는 뜻은 아니에요. 실제 분기는 getter가 스택을 주었는지 확인해요.', '스택을 얻지 못하면 arch_stack_walk_reliable을 부르지 않아요. 존재하지 않는 스택을 강제로 읽거나 NULL을 넘겨 끝까지 순회하지 않아요. put_task_stack도 호출하지 않으므로 얻지 않은 참조를 반납하지 않아요.', '이 0은 저장한 주소가 없는 결과예요. 기능이 빠진 빌드에서 대체 함수가 주는 -ENOSYS와 달라요. ENOSYS는 이 기능이 구현되지 않았다는 오류 이름이에요. 빈 결과와 기능 자체의 부재를 구분해야 해요.', '스택을 얻은 경로에서는 walker가 검사하고 오류가 있으면 오류를 반환해요. 배열에 몇 주소가 써졌어도 음수 오류면 신뢰 가능한 성공 개수로 읽지 않아요. 0·양수 개수·음수 오류의 뜻을 함수의 계약에 맞춰 나누어요.', '반환 숫자 하나만으로 실행된 모든 경로를 알아낼 수는 없어요. 용량이나 실제 경로가 비었는지 같은 조건도 함께 봐야 해요. 특히 용량 0이면 모든 기종의 reliable walker가 반드시 성공 0을 준다고 가정하지 않아요. 완전하게 수집했는지의 판단은 CPU별 구현도 관여해요.'], [('스택을 얻지 못한 reliable wrapper는 무엇을 반환하나요?', ['언제나 -ENOSYS예요', '0이에요'], '정답은 두 번째예요. 본문의 getter 실패 분기는 return 0이에요. -ENOSYS는 헤더의 기능 미지원 대체 구현이 주는 다른 결과예요.'), ('이 스택 부재 경로에서도 arch_stack_walk_reliable을 부르나요?', ['아니요. getter 실패 직후 돌아가요', '네. NULL 스택을 무조건 탐색해요'], '정답은 첫 번째예요. return이 walker 호출보다 앞에 있어요. 빈 결과를 알리기 위해 실제 없는 스택을 읽는 것은 아니에요.')]), 'os1955': ('가게가 열려 있는데 주문이 0개인 것과, 그 서비스를 제공하지 않는 것은 달라요. 미지원 오류를 0개 성공으로 바꾸면 상황을 잘못 이해하게 돼요.', '조건부 reliable stub와 음수 결과 확인 순서를 이해합니다.', '함수 결과를 int로 받고, 음수면 오류 처리·0 이상이면 개수로 처리하는 화살표를 그리세요.', ['헤더의 조건은 CONFIG_STACKTRACE와 CONFIG_HAVE_RELIABLE_STACKTRACE가 모두 정의됐는지 확인해요. &&는 두 조건이 모두 맞아야 한다는 뜻이에요. 이때 실제 reliable 수집 API의 함수 선언을 제공해요.', '두 설정 중 하나라도 빠지면 else 쪽의 작은 inline 함수가 제공돼요. 이런 대체 구현을 stub라고 해요. 본문은 입력 스택을 읽지 않고 -ENOSYS를 반환해 기능 미지원을 알려요.', '0은 이 API에서 주소 개수가 0인 결과일 수 있지만 -ENOSYS는 기능이 없다는 오류예요. 둘을 같은 빈 성공으로 처리하면 왜 주소를 못 얻었는지 알 수 없게 돼요. 오류 이름의 실제 숫자를 외우기보다 의미와 부호를 확인해요.', '반환형은 int예요. int는 음수 오류를 표현할 수 있으므로 결과를 그대로 받아 result<0부터 확인해요. 음수이면 오류 경로로 가고 그 밖의 값만 결과 개수로 사용해요.', '처음부터 unsigned 변수에 넣으면 음수가 큰 양수로 바뀔 수 있어요. 원리 예로 32비트 unsigned에 -1을 넣으면 4294967295가 돼요. 이것을 배열 항목 수라고 믿으면 준비한 용량보다 훨씬 많이 읽으려 할 수 있어요. 이 예는 -ENOSYS의 실제 숫자가 -1이라는 뜻은 아니에요.', '이 stub가 있다고 모든 스택 추적 함수도 같은 대체 구현을 가진 것은 아니에요. 함수마다 #if·#else 범위와 본문을 확인해야 해요. 컴파일 때 기능을 선택하는 것과 실행 중 스택이 비어 있는 것은 서로 다른 조건이에요.'], [('기능 미지원 reliable stub가 반환하는 값은 무엇인가요?', ['성공한 빈 결과 0이에요', '-ENOSYS예요'], '정답은 두 번째예요. 실제 else 본문에 return -ENOSYS가 있어요. 수집 기능이 없는 상태를 주소 0개 수집 성공과 구별해요.'), ('reliable 결과를 배열 개수로 쓰기 전에 무엇을 해야 하나요?', ['int로 받은 결과가 음수 오류인지 먼저 확인해요', '먼저 unsigned로 바꾸고 큰 숫자를 그대로 믿어요'], '정답은 첫 번째예요. 음수 오류를 부호 없는 수로 바꾸면 큰 개수처럼 보일 수 있어요. 오류 처리 뒤 성공 개수만 사용해야 해요.')]), 'os1956': ('사용자 프로그램의 지나온 길을 찾으려면 그 프로그램의 실행 출발 정보가 필요해요. 커널 일을 위한 스레드는 먼저 구별해요.', '사용자 스택 수집의 커널 스레드 검사와 레지스터 전달을 이해합니다.', 'PF_KTHREAD 있음 → 0 반환, 없음 → task_pt_regs(current) 전달 → 사용자 walker 호출을 그리세요.', ['사용자 공간은 일반 프로그램이 실행되는 영역이고 커널은 운영체제의 중심 코드예요. stack_trace_save_user는 현재 태스크의 사용자 호출 경로를 모으는 함수예요. 여기서는 CONFIG_ARCH_STACKWALK와 사용자 추적 지원이 있는 경로를 읽어요.', 'PF_KTHREAD는 태스크가 커널 스레드임을 나타내는 플래그예요. 플래그는 특정 상태가 켜져 있는지 나타내는 비트 표시예요. current->flags & PF_KTHREAD는 현재 태스크에 그 표시가 있는지 확인해요.', '표시가 있으면 즉시 0을 반환해 사용자 walker를 부르지 않아요. 이 경로에서 커널 스레드를 일반 사용자 실행 경로처럼 읽으려 하지 않는 것이에요. 조건은 외부 탐색 함수 호출보다 먼저 실행돼요.', '표시가 없으면 task_pt_regs(current)로 현재 태스크의 저장 레지스터 정보 위치를 얻어 arch_stack_walk_user에 전달해요. 이것은 결과 배열 끝 주소와 다른 대상이에요. 레지스터 정보는 탐색 출발 상태이고 store는 찾은 주소를 넣을 출력 공간이에요.', '수집 상태의 store와 size를 준비하고 생략된 skip과 len은 0으로 초기화해요. 일반 콜백을 사용하므로 시작 건너뛰기는 0이며 배열 용량 안에서 주소를 모아요. 끝나면 실제 저장 개수 c.len을 반환해요.', '이 공통 함수는 사용자 메모리를 어떻게 읽고 잘못된 접근을 어떻게 처리할지 모두 구현하지 않아요. 그 일은 CPU별 사용자 walker 등 관련 구현을 봐야 해요. 가상 주소 목록으로 전달 순서를 연습한 것을 실제 사용자 스택 접근과 오류 처리 검증으로 확대하지 않아요.'], [('이 사용자 수집 경로에서 PF_KTHREAD가 켜져 있으면 무엇을 하나요?', ['무조건 모든 사용자 주소를 읽어요', '0을 반환하고 사용자 walker를 부르지 않아요'], '정답은 두 번째예요. 플래그 검사에서 조기 반환해요. 커널 스레드의 상태를 일반 사용자 실행 상태처럼 무조건 탐색하지 않아요.'), ('사용자 walker에 줄 regs는 어디서 얻나요?', ['task_pt_regs(current)에서 얻어요', '언제나 출력 배열의 마지막 칸에서 얻어요'], '정답은 첫 번째예요. 현재 태스크의 저장 레지스터 정보예요. 출발 상태를 주는 인수와 결과를 담는 배열을 구분해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_484.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
